import { readFileSync, writeFileSync } from 'fs'
import { dirname, resolve } from 'path'
import { fileURLToPath } from 'url'

import { parseIndexExports } from '../src/nuxt/codegen/parse-index-exports.mjs'

const rootDir = dirname(dirname(fileURLToPath(import.meta.url)))
const indexSource = readFileSync(resolve(rootDir, 'src/index.ts'), 'utf-8')
const entries = parseIndexExports(indexSource)

// Formatted to match this repo's eslint style (single quotes, unquoted keys,
// no semicolons, trailing comma) even though the generated file itself is
// gitignored and excluded from linting — so it still reads like normal code.
const entryLines = entries
  .map(({ name, filePath }) => `  { name: '${name}', filePath: '${filePath}' },`)
  .join('\n')

const outFile = resolve(rootDir, 'src/nuxt/generated-components.ts')
// Type inlined rather than imported from `./codegen/parse-index-exports.d.mts`:
// that file isn't copied into `dist/` by `build:types` (nothing else needs
// it there), so a published `dist/nuxt/generated-components.d.ts` importing
// it would point at a path that doesn't exist in the npm package.
const outContents = `// Auto-generated by \`npm run generate:nuxt-components\` — do not edit by hand.
export const nuxtComponents: { name: string, filePath: string }[] = [
${entryLines}
]
`

writeFileSync(outFile, outContents)

console.log(`Generated ${entries.length} Nuxt-auto-import component entries.`)
